 pub fn first_sentence(text: &str) -> String {
    let text = text.trim();
    // The first sentence ends at the first occurrence of a period, question mark,
    // or exclamation mark followed by a space (or end-of-string).
    // Stop before parentheses or brackets that might contain citations.
    if let Some(end) = text.find(|c: char| ".?!".contains(c)) {
        // Advance past the punctuation, the optional close-quote, and a space.
        let after = text[end+1..].trim_start();
        match after.find(' ') {
            Some(space) => {
                // Include the punctuation and everything up to the space
                let real_end = end + 1 + space; // space is relative to after, so add end+1
                text[..=real_end].trim_end_matches(|c: char| c == ' ').to_string()
            },
            None => text.trim_end_matches(|c: char| ".?! ".contains(c)).to_string(),
        }
    } else {
        text.to_string()
    }
}
